using System;
using System.Linq;
using CashflowChains.City;
using CashflowChains.Economy;
namespace CashflowChains.Empire {
 public sealed partial class EmpireEngine {
  public CommandReceipt EnterMetropolis(long now)=>Command("city-region-entry-v2","established-metropolis-v2","city-context","metropolis-entry",now,(a,t)=>{var city=RequiredCity(a);if(city.Region<1)throw new InvalidOperationException("Enter the region before the metropolis");city.Region=2;city.Width=Math.Max(city.Width,CityMetropolis.Size);city.Height=Math.Max(city.Height,CityMetropolis.Size);});
  public CityInvestmentQuote QuoteCityAcquisition(int publicId){lock(gate){var actual=state.Copy();var city=RequiredCity(actual);var asset=CityMetropolis.Building(publicId)??throw new ArgumentException("Unknown asset");if(asset.OfferPrice<1)throw new InvalidOperationException("This property is not offered for sale");var projected=ProjectNextCityDay(actual.Copy());var next=projected.City;long before=ForecastCity().Net;var cash=projected.Economy.Balances.Single(b=>b.ItemId=="CASH");cash.Earned=Math.Max(0,cash.Earned+cash.Purchased-asset.OfferPrice);cash.Purchased=0;next.Properties.Add(new CityProperty{Id=next.NextPropertyId++,AcquiredFrom=asset.Id,Kind=asset.Kind,Level=1,X=asset.X,Y=asset.Y,Staff=config.City.Business(asset.Kind).BaseStaff});var report=CityDayModel.Forecast(config.City,OperatingPlan(config,projected,Math.Max(1,projected.Economy.LastTrustedAt)));long after=report.Net;var row=report.Businesses.Single(b=>b.PropertyId==next.NextPropertyId-1);return new CityInvestmentQuote{Kind=asset.Kind,PropertyId=asset.Id,X=asset.X,Y=asset.Y,Seconds=3,BeforeNet=before,AfterNet=after,AssetRevenue=row.Revenue,AssetCosts=row.Bills+row.Imports+row.Tax,AssetNet=row.Net,Costs=new[]{new ItemAmount("CASH",asset.OfferPrice)},Owned=new[]{new ItemAmount("CASH",actual.Economy.Amount("CASH"))},Unlocked=city.Region>=2&&city.Day>=asset.AvailableDay&&!city.Properties.Any(p=>p.X==asset.X&&p.Y==asset.Y),Affordable=actual.Economy.Amount("CASH")>=asset.OfferPrice,BuilderAvailable=city.Jobs.Count<city.BuilderSlots};}}
  public CommandReceipt AcquireCityProperty(string id,int publicId,long now)=>Command(id,publicId.ToString(),"city-acquisition","asset-purchase",now,(a,t)=>{var city=RequiredCity(a);var asset=CityMetropolis.Building(publicId)??throw new ArgumentException("Unknown city property");if(city.Region<2||asset.OfferPrice<1||city.Day<asset.AvailableDay)throw new InvalidOperationException("This asset is not currently offered for sale");if(city.Properties.Any(p=>p.X==asset.X&&p.Y==asset.Y))throw new InvalidOperationException("This asset is already acquired or transferring");if(city.Jobs.Count>=city.BuilderSlots)throw new InvalidOperationException("Complete the current transfer or development first");t.Spend("CASH",asset.OfferPrice);var p=new CityProperty{Id=city.NextPropertyId++,AcquiredFrom=asset.Id,AcquisitionId=id,X=asset.X,Y=asset.Y,Kind=asset.Kind,Level=0,Staff=config.City.Business(asset.Kind).BaseStaff};city.Properties.Add(p);city.Jobs.Add(new CityBuildingJob{Id=id,Acquisition=true,PropertyId=p.Id,TargetLevel=1,Seconds=3,StartedAt=now,FinishAt=checked(now+3)});});
 }
}
